from typing import List, Tuple
def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a given list of integers, return a tuple consisting of a sum and a product of all the integers in a list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    if not numbers:
        return (0, 1)
    total = sum(numbers)
    product = 1
    for n in numbers:
        product *= n
    return (total, product)

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    return string.swapcase()

def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    return sorted(set(l))

import math
def is_prime(num: int) -> bool:
    """Return True if num is prime, False otherwise."""
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    limit = int(math.isqrt(num))
    for i in range(3, limit + 1, 2):
        if num % i == 0:
            return False
    return True
def prime_fib(n: int) -> int:
    """
    Return the n-th number that is both a Fibonacci number and prime.
    """
    count = 0
    a, b = 0, 1  # start of Fibonacci sequence: 0, 1, 1, 2, 3, 5, ...
    while count < n:
        a, b = b, a + b
        if is_prime(b):
            count += 1
    return b

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def vowels_count(s):
    """
    Counts vowels in a word. Vowels: a, e, i, o, u (case-insensitive).
    'y' is also a vowel if it is the last character of the word.
    """
    count = 0
    s_lower = s.lower()
    for i, ch in enumerate(s_lower):
        if ch in 'aeiou':
            count += 1
        elif ch == 'y' and i == len(s) - 1:
            count += 1
    return count

def digitSum(s):
    """Return the sum of ASCII codes of uppercase characters in the input string."""
    return sum(ord(ch) for ch in s if ch.isupper())

def pluck(arr):
    """
    Given an array representing a branch of a tree that has non-negative integer nodes,
    pluck the node with the smallest even value. If multiple, return the one with the smallest index.
    Returns [value, index] or [] if no even values or empty array.
    """
    best_value = None
    best_index = None
    for i, val in enumerate(arr):
        if val % 2 == 0:
            if best_value is None or val < best_value or (val == best_value and i < best_index):
                best_value = val
                best_index = i
    if best_value is None:
        return []
    return [best_value, best_index]

def numerical_letter_grade(grades):
    """It is the last week of the semester and the teacher has to give the grades
    to students. The teacher has been making her own algorithm for grading.
    The only problem is, she has lost the code she used for grading.
    She has given you a list of GPAs for some students and you have to write 
    a function that can output a list of letter grades using the following table:
             GPA       |    Letter grade
              4.0                A+
            > 3.7                A 
            > 3.3                A- 
            > 3.0                B+
            > 2.7                B 
            > 2.3                B-
            > 2.0                C+
            > 1.7                C
            > 1.3                C-
            > 1.0                D+ 
            > 0.7                D 
            > 0.0                D-
              0.0                E


    Example:
    grade_equation([4.0, 3, 1.7, 2, 3.5]) ==> ['A+', 'B', 'C-', 'C', 'A-']
    """
    result = []
    for gpa in grades:
        if gpa == 4.0:
            result.append('A+')
        elif gpa == 0.0:
            result.append('E')
        else:
            if gpa > 3.7:
                result.append('A')
            elif gpa > 3.3:
                result.append('A-')
            elif gpa > 3.0:
                result.append('B+')
            elif gpa > 2.7:
                result.append('B')
            elif gpa > 2.3:
                result.append('B-')
            elif gpa > 2.0:
                result.append('C+')
            elif gpa > 1.7:
                result.append('C')
            elif gpa > 1.3:
                result.append('C-')
            elif gpa > 1.0:
                result.append('D+')
            elif gpa > 0.7:
                result.append('D')
            elif gpa > 0.0:
                result.append('D-')
            else:
                # Should not happen for valid GPAs, but fallback
                result.append('E')
    return result

def prime_length(string):
    """Return True if the length of the string is a prime number, else False."""
    n = len(string)
    if n < 2:
        return False
    # Check divisibility up to sqrt(n)
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")
    if n == 1:
        return 1  # only the number 1
    # For n >= 2: count = 10^(n-1) + 9*10^(n-2) - 10^(n-2) = 18 * 10^(n-2)
    return 18 * (10 ** (n - 2))

def add(lst):
    """Given a non-empty list of integers lst. add the even elements that are at odd indices.

    Examples:
        add([4, 2, 6, 7]) ==> 2 
    """
    return sum(lst[i] for i in range(1, len(lst), 2) if lst[i] % 2 == 0)

def encode(message):
    """
    Encodes a message by swapping the case of all letters and replacing
    each vowel with the letter that appears 2 places ahead in the alphabet.
    Assumes the input contains only letters.
    """
    result = []
    for ch in message:
        # Swap case
        swapped = ch.swapcase()
        # If the swapped character is a vowel, replace with the letter 2 steps ahead
        if swapped.lower() in 'aeiou':
            result.append(chr(ord(swapped) + 2))
        else:
            result.append(swapped)
    return ''.join(result)

def is_prime(n):
    """Return True if n is a prime number, False otherwise."""
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True
def skjkasdkd(lst):
    """You are given a list of integers.
    You need to find the largest prime value and return the sum of its digits.

    Examples:
    For lst = [0,3,2,1,3,5,7,4,5,5,5,2,181,32,4,32,3,2,32,324,4,3] the output should be 10
    For lst = [1,0,1,8,2,4597,2,1,3,40,1,2,1,2,4,2,5,1] the output should be 25
    For lst = [1,3,1,32,5107,34,83278,109,163,23,2323,32,30,1,9,3] the output should be 13
    For lst = [0,724,32,71,99,32,6,0,5,91,83,0,5,6] the output should be 11
    For lst = [0,81,12,3,1,21] the output should be 3
    For lst = [0,8,1,2,1,7] the output should be 7
    """
    max_prime = None
    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num
    # According to the examples, a prime is always present.
    # If not, return 0 (or raise an exception, but we follow the spec).
    if max_prime is None:
        return 0
    return sum(int(d) for d in str(max_prime))

def count_up_to(n):
    """Return a list of all prime numbers less than n."""
    if n <= 2:
        return []
    # Sieve of Eratosthenes
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False
    return [i for i in range(2, n) if is_prime[i]]

def select_words(s, n):
    """
    Given a string s and a natural number n, returns a list of all words from s
    that contain exactly n consonants, in the order they appear.
    If s is empty, returns an empty list.
    """
    if not s:
        return []

    vowels = set('aeiou')
    words = s.split()  # splits on whitespace, handles multiple spaces
    result = []

    for word in words:
        consonant_count = 0
        for ch in word:
            if ch.lower() not in vowels:
                consonant_count += 1
        if consonant_count == n:
            result.append(word)

    return result

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # Check if any whitespace character exists
    if any(c.isspace() for c in txt):
        return txt.split()
    # Check if comma exists
    if ',' in txt:
        return txt.split(',')
    # Otherwise, count lowercase letters with odd alphabet index
    count = 0
    for c in txt:
        if c.islower():
            # ord('a') = 97, so index = ord(c) - 97
            if (ord(c) - ord('a')) % 2 == 1:
                count += 1
    return count

def is_sorted(lst):
    """
    Returns True if the list is sorted in ascending order and no number
    appears more than twice. Otherwise returns False.
    """
    # Check ascending order
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False

    # Check for more than one duplicate (i.e., three or more occurrences)
    seen = {}
    for num in lst:
        seen[num] = seen.get(num, 0) + 1
        if seen[num] > 2:
            return False

    return True

def minPath(grid, k):
    """
    Returns the lexicographically smallest path of length k in the grid.
    """
    n = len(grid)
    # Find the cell containing 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                r, c = i, j
                break
        else:
            continue
        break

    path = []
    for _ in range(k):
        path.append(grid[r][c])
        # Find the neighbor with the smallest value
        best_val = float('inf')
        best_r, best_c = None, None
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if grid[nr][nc] < best_val:
                    best_val = grid[nr][nc]
                    best_r, best_c = nr, nc
        r, c = best_r, best_c
    return path

import math
def sum_squares(lst):
    """Return the sum of squared numbers after rounding each element to the ceiling."""
    return sum(math.ceil(x) ** 2 for x in lst)

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def to_float(x):
        if isinstance(x, str):
            # Replace comma with dot for decimal conversion
            return float(x.replace(',', '.'))
        return float(x)

    a_val = to_float(a)
    b_val = to_float(b)

    if a_val > b_val:
        return a
    elif b_val > a_val:
        return b
    else:
        return None

import re
def fix_spaces(text):
    """
    Given a string text, replace all spaces in it with underscores, 
    and if a string has more than 2 consecutive spaces, 
    then replace all consecutive spaces with - 

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    def replacer(match):
        spaces = match.group()
        if len(spaces) > 2:
            return '-'
        else:
            # Replace each space with an underscore
            return '_' * len(spaces)

    return re.sub(r' +', replacer, text)

def bf(planet1, planet2):
    '''
    Returns a tuple of all planets whose orbits lie between the orbits of
    planet1 and planet2, sorted by proximity to the Sun.
    Returns an empty tuple if either planet name is invalid.
    '''
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in planets or planet2 not in planets:
        return ()

    i1 = planets.index(planet1)
    i2 = planets.index(planet2)

    # Determine the range of indices strictly between the two planets
    start = min(i1, i2) + 1
    end = max(i1, i2)

    return tuple(planets[start:end])

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    if n <= 1:
        return y
    if n == 2:
        return x
    if n % 2 == 0:
        return y
    # Check divisors from 3 to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            return y
        i += 2
    return x
